{
  "code": "export default async function ({ page }) {
  const EMAIL = 'jessicamendesbarbosa5@gmail.com';
  const SENHA = 'amovoced28';
  const wait = (ms) => new Promise(r => setTimeout(r, ms));

  try {
    await page.setViewport({ width: 1280, height: 800 });

    // === LOGIN ===
    await page.goto('https://app.cotadorsimplificado.com.br/login', { waitUntil: 'networkidle2', timeout: 60000 });
    await wait(2000);

    const emailInput = await page.$('#email_principal');
    if (emailInput) {
      await emailInput.click();
      await emailInput.type(EMAIL, { delay: 30 });
    }
    await wait(1000);

    let buttons = await page.$$('button');
    for (const btn of buttons) {
      const text = await page.evaluate(el => el.textContent, btn);
      if (text && text.includes('Continuar com Email')) {
        await btn.click();
        break;
      }
    }
    await wait(2000);

    await page.waitForSelector('#pwdInput', { timeout: 15000 });
    const senhaInput = await page.$('#pwdInput');
    if (senhaInput) {
      await senhaInput.click();
      await senhaInput.type(SENHA, { delay: 30 });
    }
    await wait(1000);

    buttons = await page.$$('button');
    for (const btn of buttons) {
      const text = await page.evaluate(el => el.textContent.trim(), btn);
      if (text === 'Entrar') {
        await btn.click();
        break;
      }
    }
    await wait(5000);

    // Hapvida
    const hapvidaImg = await page.$('img[src*=\"hapvida\"]');
    if (hapvidaImg) {
      const parent = await hapvidaImg.evaluateHandle(el => el.closest('.clickable-element') || el.parentElement.parentElement);
      await parent.click();
      await wait(3000);
    }

    // === FORMULARIO ===
    await page.goto('https://app.cotadorsimplificado.com.br/?produto=hap', { waitUntil: 'domcontentloaded', timeout: 60000 });
    await wait(3000);

    // PME
    await page.evaluate(() => {
      const pme = [...document.querySelectorAll('.clickable-element')].find(e => e.textContent.includes('PME') && e.textContent.includes('29'));
      if (pme) pme.click();
    });
    await wait(2000);

    // Nome
    await page.waitForSelector('#id-nomelead', { timeout: 10000 });
    const nomeInput = await page.$('#id-nomelead');
    if (nomeInput) {
      await nomeInput.click();
      await nomeInput.type('teste', { delay: 20 });
    }

    // Avancar 1
    await page.evaluate(() => {
      const btn = [...document.querySelectorAll('button')].find(b => b.textContent.includes('Avan'));
      if (btn) btn.click();
    });
    await wait(3000);

    // Cidade
    await page.waitForSelector('#cidade_nome', { timeout: 10000 });
    const cidadeInput = await page.$('#cidade_nome');
    if (cidadeInput) {
      await cidadeInput.click();
      await cidadeInput.type('teresina', { delay: 80 });
    }
    await wait(2000);

    // Clica Teresina
    const teresinaCoords = await page.evaluate(() => {
      const clickables = document.querySelectorAll('.clickable-element');
      for (const el of clickables) {
        if (el.textContent.trim() === 'Teresina - PI') {
          const rect = el.getBoundingClientRect();
          if (rect.width > 0) return { x: rect.x + rect.width / 2, y: rect.y + rect.height / 2 };
        }
      }
      return null;
    });
    if (teresinaCoords) await page.mouse.click(teresinaCoords.x, teresinaCoords.y);
    await wait(2000);

    // MEI
    try {
      await page.waitForSelector('select.Dropdown', { timeout: 5000 });
      await page.select('select.Dropdown', '\"mei___empres_rio_individual\"');
    } catch(e) {}
    await wait(1000);

    // Avancar 2
    const btns2 = await page.$$('button');
    for (const btn of btns2) {
      const info = await page.evaluate(el => {
        const s = window.getComputedStyle(el);
        return { t: el.textContent, d: s.display, v: s.visibility };
      }, btn);
      if (info.t && info.t.includes('Avan') && info.d !== 'none' && info.v !== 'hidden') {
        await btn.click();
        break;
      }
    }
    await wait(3000);

    // === FAIXAS ===
    await page.evaluate(() => {
      document.querySelectorAll('input').forEach(inp => {
        const r = inp.getBoundingClientRect();
        const s = window.getComputedStyle(inp);
        if (r.width > 0 && s.display !== 'none' && !inp.id && inp.placeholder === '0' && inp.className.includes('cocys')) {
          inp.focus();
          inp.value = '1';
          inp.dispatchEvent(new Event('input', { bubbles: true }));
          inp.dispatchEvent(new Event('change', { bubbles: true }));
        }
      });
    });
    await wait(1500);

    // Avancar 3
    const btns3 = await page.$$('button');
    for (const btn of btns3) {
      const info = await page.evaluate(el => {
        const s = window.getComputedStyle(el);
        return { t: el.textContent, d: s.display, v: s.visibility };
      }, btn);
      if (info.t && info.t.includes('Avan') && info.d !== 'none' && info.v !== 'hidden') {
        await btn.click();
        break;
      }
    }
    await wait(3000);

    // === MODAL ===
    // Add Produtos
    const btns4 = await page.$$('button');
    for (const btn of btns4) {
      const info = await page.evaluate(el => {
        const s = window.getComputedStyle(el);
        return { t: el.textContent.trim(), d: s.display, v: s.visibility };
      }, btn);
      if (info.t === 'Add Produtos' && info.d !== 'none' && info.v !== 'hidden') {
        await btn.click();
        break;
      }
    }
    await wait(2500);

    // Hapvida
    const hapCoords = await page.evaluate(() => {
      for (const el of document.querySelectorAll('.clickable-element')) {
        if (el.textContent.trim() === 'Hapvida') {
          const r = el.getBoundingClientRect();
          if (r.width > 0) return { x: r.x + r.width/2, y: r.y + r.height/2 };
        }
      }
      return null;
    });
    if (hapCoords) await page.mouse.click(hapCoords.x, hapCoords.y);
    await wait(2500);

    // Tabela Teresina
    const tabCoords = await page.evaluate(() => {
      for (const el of document.querySelectorAll('.clickable-element')) {
        const t = el.textContent.trim();
        if (t.includes('Teresina') && t.includes('2') && t.includes('29')) {
          const r = el.getBoundingClientRect();
          if (r.width > 0) return { x: r.x + r.width/2, y: r.y + r.height/2 };
        }
      }
      return null;
    });
    if (tabCoords) await page.mouse.click(tabCoords.x, tabCoords.y);
    await wait(2000);

    // Ambulatorial
    const ambCoords = await page.evaluate(() => {
      for (const el of document.querySelectorAll('.clickable-element')) {
        if (el.textContent.trim() === 'Ambulatorial') {
          const r = el.getBoundingClientRect();
          if (r.width > 0) return { x: r.x + r.width/2, y: r.y + r.height/2 };
        }
      }
      return null;
    });
    if (ambCoords) await page.mouse.click(ambCoords.x, ambCoords.y);
    await wait(2000);

    // Acomodacao
    const acoCoords = await page.evaluate(() => {
      for (const el of document.querySelectorAll('.clickable-element')) {
        const t = el.textContent.trim().toLowerCase();
        if (t.includes('sem acomodação') && t.includes('coparticipação')) {
          const r = el.getBoundingClientRect();
          if (r.width > 0) return { x: r.x + r.width/2, y: r.y + r.height/2 };
        }
      }
      return null;
    });
    if (acoCoords) await page.mouse.click(acoCoords.x, acoCoords.y);
    await wait(2000);

    // Fecha modal
    await page.mouse.click(1200, 400);
    await wait(3000);

    // === EXTRAI ===
    const faixas = await page.evaluate(() => {
      const nomes = ['0 a 18 anos','19 a 23 anos','24 a 28 anos','29 a 33 anos','34 a 38 anos','39 a 43 anos','44 a 48 anos','49 a 53 anos','54 a 58 anos','59 anos ou mais'];
      const vals = [];
      const regex = /^\d{2,3}[,.]\d{2}$/;
      document.querySelectorAll('div, span').forEach(el => {
        const s = window.getComputedStyle(el);
        const r = el.getBoundingClientRect();
        if (s.display !== 'none' && r.width > 0 && el.textContent.length < 15) {
          const t = el.textContent.trim();
          if (regex.test(t) && !vals.some(v => v.text === t) && r.y > 650 && r.x > 150 && r.x < 280) {
            vals.push({ text: t, y: r.y });
          }
        }
      });
      vals.sort((a,b) => a.y - b.y);
      return vals.slice(0,10).map((v,i) => ({ faixa_etaria: nomes[i], valor: 'R$ ' + v.text.replace('.',',') }));
    });

    const screenshot = await page.screenshot({ encoding: 'base64' });
    const url = page.url();
    const pageText = await page.evaluate(() => document.body.innerText.substring(0, 1000));

    return { success: true, faixas, screenshot, url, pageText };
  } catch (error) {
    const screenshot = await page.screenshot({ encoding: 'base64' }).catch(() => null);
    return { success: false, error: error.message, screenshot };
  }
}"
}
